const rows = $input.all();
const now = new Date();

const reportDate = now.toLocaleDateString("en-GB", {
  timeZone: "Asia/Dhaka",
  day: "2-digit",
  month: "short",
  year: "numeric"
});

const generatedAt = now.toLocaleString("en-GB", {
  timeZone: "Asia/Dhaka",
  day: "2-digit",
  month: "short",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  hour12: true
});

// Unique report reference for each execution
const reportId =
  "WOR-" +
  new Date().toLocaleDateString("en-CA", {
    timeZone: "Asia/Dhaka"
  }).replace(/-/g, "") +
  "-" +
  String(Date.now()).slice(-6);

// Escape values before inserting spreadsheet content into HTML
function esc(value) {
  return String(value ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[c]);
}

function getStatus(status) {
  const s = String(status ?? "").trim().toLowerCase();

  if (s === "approved") {
    return { label: "Approved", cls: "approved" };
  }

  if (s === "cancelled") {
    return { label: "Cancelled", cls: "cancelled" };
  }

  if (s === "pending") {
    return { label: "Pending", cls: "pending" };
  }

  return {
    label: String(status ?? "").trim() || "Not specified",
    cls: "other"
  };
}

// Assumes input contains all work orders to include in the report.
const total = rows.length;

const pending = rows.filter(r =>
  String(r.json["Status"] ?? "").trim().toLowerCase() === "pending"
).length;

const approved = rows.filter(r =>
  String(r.json["Status"] ?? "").trim().toLowerCase() === "approved"
).length;

const cancelled = rows.filter(r =>
  String(r.json["Status"] ?? "").trim().toLowerCase() === "cancelled"
).length;

const tableRows = rows.map((row, index) => {
  const status = getStatus(row.json["Status"]);

  return `
    <tr>
      <td class="serial">${index + 1}</td>
      <td class="job-no">${esc(row.json["Job No"])}</td>
      <td class="client">${esc(row.json["Client Name"])}</td>
      <td class="status-cell">
        <span class="badge ${status.cls}">${esc(status.label)}</span>
      </td>
    </tr>
  `;
}).join("");

const emptyRow = `
  <tr>
    <td colspan="4" class="empty-row">
      No work orders are available for this report.
    </td>
  </tr>
`;

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">

<title>Daily Work Order Report</title>

<style>
  @page {
    size: A4 portrait;
    margin: 14mm 12mm 16mm 12mm;
  }

  * {
    box-sizing: border-box;
  }

  body {
    margin: 0;
    color: #243247;
    background: #ffffff;
    font-family: Arial, Helvetica, sans-serif;
    font-size: 10pt;
    line-height: 1.55;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .report {
    width: 100%;
    max-width: 100%;
    margin: 0 auto;
  }

  .header {
    background: #12345a;
    color: #ffffff;
    padding: 25px 26px;
    border-bottom: 5px solid #159a9c;
  }

  .department {
    margin: 0 0 8px;
    color: #9ce8e3;
    font-size: 9pt;
    font-weight: 700;
    letter-spacing: 1.3px;
    text-transform: uppercase;
  }

  h1 {
    margin: 0;
    color: #ffffff;
    font-size: 23pt;
    line-height: 1.25;
    letter-spacing: -0.4px;
  }

  .header-subtitle {
    margin: 9px 0 0;
    color: #dbe7f5;
    font-size: 10pt;
  }

  .meta {
    display: table;
    width: 100%;
    table-layout: fixed;
    margin: 0 0 23px;
    background: #f3f7fb;
    border: 1px solid #dce5ef;
  }

  .meta-item {
    display: table-cell;
    width: 50%;
    padding: 12px 15px;
    vertical-align: top;
  }

  .meta-item + .meta-item {
    border-left: 1px solid #dce5ef;
  }

  .meta-label {
    display: block;
    color: #697b90;
    font-size: 8pt;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: .5px;
  }

  .meta-value {
    display: block;
    margin-top: 3px;
    color: #183b63;
    font-size: 10pt;
    font-weight: 700;
    overflow-wrap: anywhere;
  }

  .content {
    padding: 22px 24px 18px;
  }

  .greeting {
    margin: 0 0 8px;
    font-size: 12pt;
    font-weight: 700;
    color: #183b63;
  }

  .intro {
    margin: 0 0 22px;
    color: #526176;
    line-height: 1.8;
  }

  h2 {
    margin: 23px 0 12px;
    padding-bottom: 8px;
    color: #183b63;
    font-size: 13pt;
    border-bottom: 2px solid #dce8f2;
    break-after: avoid;
    page-break-after: avoid;
  }

  .summary {
    display: table;
    width: 100%;
    table-layout: fixed;
    border-spacing: 6px 0;
    margin: 0 0 22px;
  }

  .summary-cell {
    display: table-cell;
    padding: 14px 5px;
    text-align: center;
    border: 1px solid #e0e8f0;
    border-radius: 5px;
    vertical-align: middle;
  }

  .summary-total { background: #eaf2ff; }
  .summary-pending { background: #fff5dd; }
  .summary-approved { background: #e7f7ee; }
  .summary-cancelled { background: #fdecec; }

  .summary-number {
    display: block;
    font-size: 22pt;
    line-height: 1.25;
    font-weight: 700;
  }

  .summary-total .summary-number { color: #2458a6; }
  .summary-pending .summary-number { color: #996515; }
  .summary-approved .summary-number { color: #187344; }
  .summary-cancelled .summary-number { color: #a92c32; }

  .summary-label {
    display: block;
    margin-top: 5px;
    color: #45556b;
    font-size: 8pt;
    font-weight: 700;
  }

  .table-wrap {
    width: 100%;
  }

  table.work-orders {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    font-size: 9pt;
  }

  .work-orders thead {
    display: table-header-group;
  }

  .work-orders tfoot {
    display: table-footer-group;
  }

  .work-orders th {
    padding: 11px 8px;
    background: #183b63;
    color: #ffffff;
    text-align: left;
    font-size: 8.5pt;
    font-weight: 700;
    border: 1px solid #183b63;
  }

  .work-orders td {
    padding: 10px 8px;
    vertical-align: middle;
    border: 1px solid #dce3eb;
    overflow-wrap: anywhere;
    word-wrap: break-word;
  }

  .work-orders tbody tr:nth-child(even) {
    background: #f5f8fc;
  }

  .work-orders tr {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  .col-sl { width: 9%; }
  .col-job { width: 25%; }
  .col-client { width: 42%; }
  .col-status { width: 24%; }

  .serial {
    text-align: center;
    color: #66758a;
  }

  .job-no {
    color: #183b63;
    font-weight: 700;
  }

  .status-cell {
    text-align: center;
  }

  .badge {
    display: inline-block;
    padding: 4px 8px;
    border-radius: 12px;
    font-size: 7.5pt;
    font-weight: 700;
    white-space: nowrap;
  }

  .approved { background: #dcfce7; color: #166534; }
  .pending { background: #fef3c7; color: #92400e; }
  .cancelled { background: #fee2e2; color: #991b1b; }
  .other { background: #e5e7eb; color: #374151; }

  .empty-row {
    padding: 25px 10px !important;
    text-align: center;
    color: #6b7280;
  }

  .closing {
    margin: 23px 0 0;
    color: #526176;
    line-height: 1.8;
  }

  .signature {
    margin-top: 18px;
    color: #34465b;
    line-height: 1.8;
  }

  .signature strong {
    color: #183b63;
  }

  .footer {
    margin-top: 20px;
    padding: 15px 24px;
    background: #f3f7fb;
    border-top: 1px solid #dce5ef;
    text-align: center;
    color: #68788c;
    font-size: 8pt;
    line-height: 1.7;
  }

  .footer strong {
    color: #183b63;
  }

  @media screen {
    body {
      background: #edf1f5;
      padding: 20px;
    }

    .report {
      max-width: 900px;
      border: 1px solid #dce5ef;
      box-shadow: 0 4px 18px rgba(22, 42, 65, .08);
    }
  }

  @media print {
    body {
      padding: 0;
      background: #ffffff;
    }

    .report {
      max-width: none;
      border: none;
      box-shadow: none;
    }

    .header,
    .summary-cell,
    .work-orders th,
    .footer {
      -webkit-print-color-adjust: exact;
      print-color-adjust: exact;
    }
  }
</style>
</head>

<body>
<div class="report">

  <header class="header">
    <p class="department">Software Department</p>
    <h1>Daily Work Order Report</h1>
    <p class="header-subtitle">
      Official operational report · Work Order Management System
    </p>
  </header>

  <main class="content">

    <section class="meta">
      <div class="meta-item">
        <span class="meta-label">Report Reference</span>
        <span class="meta-value">${esc(reportId)}</span>
      </div>
      <div class="meta-item">
        <span class="meta-label">Reporting Date</span>
        <span class="meta-value">${esc(reportDate)}</span>
      </div>
    </section>

    <p class="greeting">Dear Team,</p>

    <p class="intro">
      Please find below the latest Daily Work Order Report issued by the
      Software Department. This document summarizes the work orders and
      their recorded processing statuses as of the report generation time.
    </p>

    <h2>Executive Summary</h2>

    <section class="summary">
      <div class="summary-cell summary-total">
        <span class="summary-number">${total}</span>
        <span class="summary-label">Total Orders</span>
      </div>
      <div class="summary-cell summary-pending">
        <span class="summary-number">${pending}</span>
        <span class="summary-label">Pending</span>
      </div>
      <div class="summary-cell summary-approved">
        <span class="summary-number">${approved}</span>
        <span class="summary-label">Approved</span>
      </div>
      <div class="summary-cell summary-cancelled">
        <span class="summary-number">${cancelled}</span>
        <span class="summary-label">Cancelled</span>
      </div>
    </section>

    <section class="meta">
      <div class="meta-item">
        <span class="meta-label">Generated On</span>
        <span class="meta-value">${esc(generatedAt)} (Bangladesh Time)</span>
      </div>
      <div class="meta-item">
        <span class="meta-label">Prepared By</span>
        <span class="meta-value">Software Department</span>
      </div>
    </section>

    <h2>Work Order Details</h2>

    <div class="table-wrap">
      <table class="work-orders">
        <colgroup>
          <col class="col-sl">
          <col class="col-job">
          <col class="col-client">
          <col class="col-status">
        </colgroup>

        <thead>
          <tr>
            <th>SL</th>
            <th>Job No</th>
            <th>Client Name</th>
            <th>Status</th>
          </tr>
        </thead>

        <tbody>
          ${tableRows || emptyRow}
        </tbody>
      </table>
    </div>

    <p class="closing">
      Please review the work orders listed above and take the necessary
      actions in accordance with the applicable operational procedures.
      For any discrepancies, please verify the source records.
    </p>

    <div class="signature">
      Best regards,<br>
      <strong>Software Department</strong><br>
    </div>

  </main>

  <footer class="footer">
    <strong>Official System-Generated Report</strong><br>
    This report was generated automatically for internal operational review.
    Please refer to the source system for the latest record updates.<br>
    Report Reference: ${esc(reportId)}
  </footer>

</div>
</body>
</html>`;

return [{
  json: {
    html,
    reportId,
    reportDate,
    generatedAt,
    pdfFileName: `Work_Order_Report_${reportDate}.pdf`
  }
}];
